CREATE TABLE users(name TEXT, phone TEXT);
INSERT INTO users VALUES ('Ann','555'), ('Bo',NULL), ('Cy',NULL);
SELECT COUNT(*) AS a, COUNT(phone) AS b FROM users;

CREATE TABLE reviews(rating INTEGER);
INSERT INTO reviews VALUES (4), (NULL), (2);
SELECT AVG(rating) AS avg_rating FROM reviews;

CREATE TABLE orders(customer_id INTEGER, status TEXT);
INSERT INTO orders VALUES (1,'paid'), (1,'paid'), (1,'void'), (2,'paid');
SELECT customer_id, status, COUNT(*) FROM orders GROUP BY customer_id, status;

CREATE TABLE visits(user_id INTEGER);
INSERT INTO visits VALUES (1), (1), (2), (3), (3), (3);
SELECT COUNT(user_id) AS a, COUNT(DISTINCT user_id) AS b FROM visits;

CREATE TABLE s(p TEXT, score INTEGER);
INSERT INTO s VALUES ('a',90), ('b',80), ('c',80), ('d',70);
SELECT p,
  ROW_NUMBER() OVER (ORDER BY score DESC, p) AS rn,
  RANK() OVER (ORDER BY score DESC) AS rk,
  DENSE_RANK() OVER (ORDER BY score DESC) AS dr
FROM s ORDER BY score DESC, p;

CREATE TABLE o(customer_id INTEGER, total REAL);
INSERT INTO o VALUES (1,10), (1,20), (2,5);
SELECT 'group' AS q, COUNT(*) AS n FROM (SELECT customer_id, SUM(total) FROM o GROUP BY customer_id);
SELECT 'window' AS q, COUNT(*) AS n FROM (SELECT customer_id, SUM(total) OVER (PARTITION BY customer_id) FROM o);

CREATE TABLE o(total REAL);
INSERT INTO o VALUES (3), (8), (12);
SELECT COUNT(total > 5) AS big FROM o;

CREATE TABLE t(day TEXT, v INTEGER);
INSERT INTO t VALUES ('d1',1), ('d2',2), ('d2',3), ('d3',4);
SELECT day, v, SUM(v) OVER (ORDER BY day) AS running FROM t ORDER BY day, v;

CREATE TABLE o(customer_id INTEGER, total REAL);
INSERT INTO o VALUES (1,10), (1,20), (2,90);
SELECT
  (SELECT AVG(total) FROM o) AS a,
  (SELECT AVG(s) FROM (SELECT SUM(total) AS s FROM o GROUP BY customer_id)) AS b;

CREATE TABLE orders(id INTEGER, total REAL);
CREATE TABLE lines(order_id INTEGER, sku TEXT);
INSERT INTO orders VALUES (1, 100);
INSERT INTO lines VALUES (1,'a'), (1,'b');
SELECT SUM(o.total) AS spent, COUNT(l.sku) AS n FROM orders o JOIN lines l ON l.order_id = o.id;
